from fastapi import FastAPI, Request
from fastapi.responses import JSONResponse, FileResponse, StreamingResponse
from fastapi.staticfiles import StaticFiles
from pydantic import BaseModel
from typing import List, Dict, Optional
import asyncio
import aiohttp
import os
import json
import datetime
import uvicorn
from pathlib import Path
import logging

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

ANTHROPIC_API_KEY = os.environ.get("ANTHROPIC_API_KEY")
CEREBRAS_API_KEY = os.environ.get("CEREBRAS_API_KEY")
XAI_API_KEY = os.environ.get("XAI_API_KEY")
EXA_API_KEY = os.environ.get("EXA_API_KEY")

MEMORY_FILE = "memory.json"
REPORT_HTML_FILE = "report.html"

class UserQuery(BaseModel):
    topic: str

app = FastAPI()
memory: Dict = {"sources": [], "insights": [], "reasoning": [], "state": {}, "agent_log": []}
research_active = False

def save_memory():
    with open(MEMORY_FILE, "w") as f:
        json.dump(memory, f, indent=2)

def load_memory():
    global memory
    if Path(MEMORY_FILE).exists():
        with open(MEMORY_FILE, "r") as f:
            memory = json.load(f)

def log_action(action: str):
    timestamp = datetime.datetime.now().isoformat()
    log_entry = {"timestamp": timestamp, "action": action}
    memory["agent_log"].append(log_entry)
    logger.info(f"[{timestamp}] {action}")
    save_memory()

async def call_claude(prompt: str, system_prompt: str = None) > str:
    if not ANTHROPIC_API_KEY:
        return "Claude API key not configured"

    try:
        async with aiohttp.ClientSession() as session:
            headers = {
                "xapikey": ANTHROPIC_API_KEY,
                "anthropicversion": "20230601",
                "contenttype": "application/json"
            }
            messages = [{"role": "user", "content": prompt}]
            if system_prompt:
                payload = {
                    "model": "claudesonnet420250514",
                    "max_tokens": 64000,
                    "system": system_prompt,
                    "messages": messages
                }
            else:
                payload = {
                    "model": "claudesonnet420250514",
                    "max_tokens": 64000,
                    "messages": messages
                }

            async with session.post("", headers=headers, json=payload, timeout=aiohttp.ClientTimeout(total=120)) as resp:
                if resp.status != 200:
                    text = await resp.text()
                    return f"Claude API error: {resp.status}  {text}"
                data = await resp.json()
                return data.get("content", [{}])[0].get("text", "")
    except Exception as e:
        return f"Claude error: {str(e)}"

async def call_gpt_oss(prompt: str) > str:
    if not CEREBRAS_API_KEY:
        return "Cerebras API key not configured"

    try:
        async with aiohttp.ClientSession() as session:
            headers = {
                "Authorization": f"Bearer {CEREBRAS_API_KEY}",
                "ContentType": "application/json"
            }
            payload = {
                "model": "gptoss120b",
                "messages": [{"role": "user", "content": prompt}],
                "max_tokens": 65000,
                "temperature": 0.7
            }
            async with session.post("", headers=headers, json=payload, timeout=aiohttp.ClientTimeout(total=120)) as resp:
                if resp.status != 200:
                    text = await resp.text()
                    return f"GPT OSS API error: {resp.status}  {text}"
                data = await resp.json()
                return data.get("choices", [{}])[0].get("message", {}).get("content", "")
    except Exception as e:
        return f"GPT OSS error: {str(e)}"

