            margin: 10px 0;
            borderleft: 3px solid 3498db;
        }}
        .reference a {{
            color: 2c5aa0;
            textdecoration: none;
            fontweight: bold;
        }}
        .reference a:hover {{
            textdecoration: underline;
        }}
        .agentlog {{
            background: fff9e6;
            padding: 20px;
            margin: 20px 0;
            borderleft: 4px solid f39c12;
            fontfamily: monospace;
            fontsize: 0.9em;
        }}
    </style>
</head>
<body>
    <h1>DeepSearch AI Research Report</h1>
    <h2>{topic}</h2>

    <div class="metadata">
        <p><strong>Generated:</strong> {datetime.datetime.now().strftime('%Y%m%d %H:%M:%S')}</p>
        <p><strong>Sources Analyzed:</strong> {len(memory["sources"])}</p>
        <p><strong>Insights Generated:</strong> {len(memory["insights"])}</p>
        <p><strong>Reasoning Steps:</strong> {len(memory["reasoning"])}</p>
        <p><strong>Agent Actions:</strong> {len(memory["agent_log"])}</p>
    </div>

    <div class="section">
        {report_content.replace(chr(10), '<br>')}
    </div>

    <h2>Research Sources</h2>
    <div class="section">
"""

    for idx, src in enumerate(memory["sources"][:30], 1):
        title = src.get('title', 'Untitled')
        url = src.get('url', '')
        report_html += f"""
        <div class="reference">
            <strong>[{idx}] {title}</strong><br>
            <a href='{url}' target='_blank'>{url}</a>
        </div>
"""

    report_html += """
    </div>

    <h2>Agent Research Log</h2>
    <div class="agentlog">
"""

    for log_entry in memory["agent_log"]:
        report_html += f"[{log_entry['timestamp']}] {log_entry['action']}<br>"

    report_html += """
    </div>
</body>
</html>
"""

    with open(REPORT_HTML_FILE, "w", encoding="utf8") as f:
        f.write(report_html)

    log_action("REPORT: Final report generated successfully")

async def agent_loop(topic: str):
    global research_active, memory
    research_active = True
    load_memory()

    memory = {"sources": [], "insights": [], "reasoning": [], "state": {"topic": topic}, "agent_log": []}
    log_action(f"Starting autonomous research on: {topic}")

    try:
        max_iterations = 15
        iteration = 0

        while iteration < max_iterations and research_active:
            iteration += 1
            log_action(f"Iteration {iteration}/{max_iterations}")

            decision = await agent_brain_decide_action(topic, memory)
            action = decision.get("action", "SEARCH")
            params = decision.get("parameters", {})

            log_action(f"Decision: {action}  {params.get('reason', '')}")

            if action == "SEARCH":
                query = params.get("query", topic)
                await execute_search_action(query)

            elif action == "ANALYZE":
                await execute_analyze_action(topic)

            elif action == "REASON":
                await execute_reason_action(topic)

            elif action == "SYNTHESIZE":
                await execute_synthesize_action(topic)

            elif action == "REPORT":
                await generate_final_report(topic)
                memory["state"]["completed"] = True
                save_memory()
                break

            await asyncio.sleep(2)

        if not memory["state"].get("completed"):
            await generate_final_report(topic)
            memory["state"]["completed"] = True
            save_memory()

    except Exception as e:
        memory["state"]["error"] = str(e)
        save_memory()
        log_action(f"ERROR: {str(e)}")
    finally:
        research_active = False

@app.post("/start")
async def start_research(query: UserQuery):
    global research_active
    if research_active:
        return JSONResponse({"status": "Research already in progress", "topic": query.topic})

    asyncio.create_task(agent_loop(query.topic))
    return JSONResponse({"status": "Research started", "topic": query.topic})

