python
import os, json, asyncio, datetime, logging, aiohttp, base64
from pathlib import Path
from typing import Dict, Any, List, Optional
import boto3
from botocore.config import Config
from fastapi import FastAPI, UploadFile, File, Form, WebSocket, WebSocketDisconnect, Request
from fastapi.responses import FileResponse, HTMLResponse, JSONResponse
from fastapi.staticfiles import StaticFiles
import uvicorn

AWS_REGION = os.getenv("AWS_REGION", "us-east-1")
EXA_API_KEY = os.getenv("EXA_API_KEY", "")
DATA_DIR = Path("./data"); DATA_DIR.mkdir(exist_ok=True)
STATE_FILE = DATA_DIR/"state.json"
REPORT_FILE = DATA_DIR/"report.html"

logging.basicConfig(level=logging.INFO)
log = logging.getLogger("agent")

app = FastAPI()
app.mount("/static", StaticFiles(directory=".", html=False), name="static")

state: Dict[str, Any] = {
    "goal": "",
    "inputs": [],
    "entities": [],
    "tasks": [],
    "sources": [],
    "insights": [],
    "timeline": [],
    "log": [],
    "running": False,
    "done": False
}
ws_clients: List[WebSocket] = []

bedrock = boto3.client("bedrock-runtime", region_name=AWS_REGION, config=Config(read_timeout=120, retries={"max_attempts": 3}))
CLAUDE_MODEL_ID = os.getenv("BEDROCK_CLAUDE_MODEL_ID", "anthropic.claude-sonnet-4-5-20250929-v1:0")

def save_state():
    STATE_FILE.write_text(json.dumps(state, indent=2, ensure_ascii=False))

async def ws_broadcast(msg: str):
    for ws in list(ws_clients):
        try:
            await ws.send_text(msg)
        except Exception:
            pass

def log_step(msg: str):
    stamp = f"[{datetime.datetime.now().strftime('%H:%M:%S')}] {msg}"
    state["log"].append(stamp)
    log.info(stamp)
    asyncio.create_task(ws_broadcast(stamp))
    save_state()

async def http_post_json(url: str, headers: Dict[str,str], payload: Dict[str,Any], timeout_sec: int = 120):
    async with aiohttp.ClientSession() as s:
        async with s.post(url, headers=headers, json=payload, timeout=aiohttp.ClientTimeout(total=timeout_sec)) as r:
            txt = await r.text()
            if r.status != 200:
                raise RuntimeError(f"HTTP {r.status}: {txt}")
            return await r.json()

async def exa_search(query: str, num: int = 10) -> List[Dict[str, str]]:
    if not EXA_API_KEY:
        return []
    payload = {"query": query, "numResults": num, "type": "auto", "contents": {"text": True}}
    headers = {"x-api-key": EXA_API_KEY, "Content-Type": "application/json"}
    try:
        data = await http_post_json("https://api.exa.ai/search", headers, payload, timeout_sec=60)
        out = []
        for it in data.get("results", []):
            out.append({"title": it.get("title","Untitled"), "url": it.get("url",""), "snippet": (it.get("text","") or "")[:1000]})
        return out
    except Exception as e:
        log_step(f"EXA error: {e}")
        return []

def claude_messages(user_text: str, system_text: Optional[str] = None):
    msgs = [{"role": "user", "content": [{"type": "text", "text": user_text}]}]
    sys = [{"type":"text","text": system_text}] if system_text else None
    return msgs, sys

def bedrock_converse(user_text: str, system_text: Optional[str] = None, max_tokens: int = 2048, temperature: float = 0.2) -> str:
    msgs, sys = claude_messages(user_text, system_text)
    resp = bedrock.converse(
        modelId=CLAUDE_MODEL_ID,
        messages=msgs,
        system=sys if sys else [],
        inferenceConfig={"maxTokens": max_tokens, "temperature": temperature, "topP": 1}
    )
    parts = resp.get("output", {}).get("message", {}).get("content", [])
    out = []
    for p in parts:
        if p.get("type") == "text":
            out.append(p.get("text",""))
    return "\n".join(out).strip()

def add_task(title: str) -> str:
    tid = f"T{len(state['tasks'])+1}"
    state["tasks"].append({"id": tid, "title": title, "status": "todo"})
    return tid

def set_task_status(tid: str, st: str):
    for t in state["tasks"]:
        if t["id"] == tid:
            t["status"] = st
            return

def add_input_record(kind: str, content: str = "", path: Optional[str] = None):
    rec = {"type": kind}
    if path: rec["path"] = path
    if content: rec["content"] = content
    state["inputs"].append(rec)

def extract_entities(text_blob: str) -> List[str]:
    prompt = f"Kérlek, listázd vesszővel elválasztva az összes fontosabb tulajdonnevet, entitást és kulcskifejezést ebből a szövegből tömören:\n\n{text_blob[:8000]}"
    out = bedrock_converse(prompt, "Magyarul válaszolj, csak a listát add vissza.")
    raw = out.replace("\n"," ").split(",")
    ents = [e.strip() for e in raw if e.strip()]
    seen = set(); dedup = []
    for e in ents:
        if e.lower() not in seen:
            seen.add(e.lower()); dedup.append(e)
    return dedup[:100]

async def build_report():
    html = f"""<!doctype html><html><head><meta charset="utf-8"><title>Agent Report</title>
    <style>body{{font-family:system-ui;margin:40px;line-height:1.6}} pre{{white-space:pre-wrap}}</style></head><body>
    <h1>Végső Jelentés</h1>
    <h3>Cél</h3><pre>{state['goal']}</pre>
    <h3>Entitások</h3><pre>{", ".join(state['entities'])}</pre>
    <h3>Források</h3><pre>{json.dumps(state['sources'], indent=2, ensure_ascii=False)}</pre>
    <h3>Insightok</h3><pre>{json.dumps(state['insights'], indent=2, ensure_ascii=False)}</pre>
    <h3>Idővonal</h3><pre>{json.dumps(state['timeline'], indent=2, ensure_ascii=False)}</pre>
    <h3>Napló</h3><pre>{json.dumps(state['log'][-400:], indent=2, ensure_ascii=False)}</pre>
    </body></html>"""
    REPORT_FILE.write_text(html, encoding="utf-8")

async def agent_run(max_minutes: int = 60):
    if state["running"]:
        log_step("Már fut egy ciklus")
        return
    state["running"] = True; state["done"] = False; save_state()
    log_step("Agent indul")
    add_task("Input triázs és entitás-kinyerés")
    add_task("Első körös keresés")
    add_task("Elemzés és következtetés")
    add_task("Szintézis + Jelentés")
    start = datetime.datetime.now()
    try:
        set_task_status("T1","doing"); log_step("T1: triázs")
        texts = [i.get("content","") for i in state["inputs"] if i["type"] in ("text","file_ocr")]
        blob = "\n".join(texts)[:24000]
        state["entities"] = extract_entities(blob) if blob.strip() else []
        state["timeline"].append({"t": datetime.datetime.now().isoformat(), "event":"triage_done"})
        set_task_status("T1","done"); save_state()
        set_task_status("T2","doing"); log_step("T2: keresés")
        query = (state["goal"] + " " + " ".join(state["entities"][:6])).strip()[:300] or state["goal"][:300]
        hits = await exa_search(query, num=16)
        state["sources"].extend(hits)
        set_task_status("T2","done"); save_state()
        set_task_status("T3","doing"); log_step("T3: elemzés")
        corpus = "\n".join([s.get("snippet","") for s in state["sources"]])[:12000]
        analysis = bedrock_converse(f"Elemezd a korpuszt és emeld ki a kulcspontokat, téziseket, ellenérveket magyarul:\n\n{corpus}", "Légy tömör és pontos.")
        if analysis: state["insights"].append(analysis)
        reasoning = bedrock_converse(f"Készíts következtetéseket, hipotéziseket és jelöld az ellentmondásokat, javasolj hiánypótló kereséseket:\n\n{analysis}", "Magyarul, pontokba szedve.")
        if reasoning: state["insights"].append(reasoning)
        set_task_status("T3","done"); save_state()
        set_task_status("T4","doing"); log_step("T4: szintézis")
        src_lines = "\n".join([f"- {s['title']} | {s['url']}" for s in state["sources"][:20]])
        synth = bedrock_converse(f"Készíts összefoglaló szintézist a források alapján magyarul és jelezd a bizonyítékok erősségét:\n{src_lines}", "Strukturált, hivatkozásbarát összefoglaló.")
        if synth: state["insights"].append(synth)
        await build_report()
        set_task_status("T4","done"); save_state()
        while (datetime.datetime.now() - start).total_seconds() < max_minutes*60:
            await asyncio.sleep(2)
            pend = [t for t in state["tasks"] if t["title"].startswith("Replan") and t["status"]=="todo"]
            if pend:
                t = pend[0]
                set_task_status(t["id"],"doing"); log_step("Replan: új input")
                texts = [i.get("content","") for i in state["inputs"] if i["type"] in ("text","file_ocr")]
                blob = "\n".join(texts)[-24000:]
                state["entities"] = extract_entities(blob) if blob.strip() else state["entities"]
                q2 = (state["goal"] + " " + " ".join(state["entities"][:8])).strip()[:300] or state["goal"][:300]
                hits2 = await exa_search(q2, num=8)
                if hits2: state["sources"].extend(hits2)
                corpus2 = "\n".join([s.get("snippet","") for s in state["sources"]][-30:])[:12000]
                a2 = bedrock_converse(f"Frissített elemzés magyarul:\n{corpus2}", "Tömör pontok.")
                r2 = bedrock_converse(f"Frissített következtetések és hiányok magyarul:\n{a2}", "Pontos javaslatok következő lépésekre.")
                if a2: state["insights"].append(a2)
                if r2: state["insights"].append(r2)
                await build_report()
                set_task_status(t["id"],"done"); save_state(); log_step("Replan kész")
        log_step("Időkeret vége")
    except Exception as e:
        log_step(f"Hiba: {e}")
    finally:
        state["running"] = False
        state["done"] = True
        await build_report()
        save_state()
        log_step("Agent kész")

@app.get("/")
async def index():
    return FileResponse("index.html")

@app.post("/start")
async def start(goal: str = Form(""), text: str = Form("")):
    if goal:
        state["goal"] = goal
    if text:
        add_input_record("text", text)
    if not state["running"]:
        asyncio.create_task(agent_run(max_minutes=60))
    return JSONResponse({"ok": True, "running": state["running"], "goal": state["goal"]})

@app.post("/upload")
async def upload(file: UploadFile = File(...)):
    content = await file.read()
    p = DATA_DIR / file.filename
    p.write_bytes(content)
    try:
        text_guess = content.decode("utf-8")
        add_input_record("file_ocr", text_guess, str(p))
    except Exception:
        add_input_record("file_bin", "", str(p))
    if state["running"]:
        if not any(t for t in state["tasks"] if t["title"].startswith("Replan") and t["status"]=="todo"):
            tid = add_task("Replan a friss input alapján"); set_task_status(tid,"todo")
    save_state()
    return JSONResponse({"ok": True, "filename": file.filename})

@app.get("/state")
async def get_state():
    return JSONResponse(state)

@app.get("/report")
async def get_report():
    if REPORT_FILE.exists():
        return FileResponse(str(REPORT_FILE), media_type="text/html")
    return JSONResponse({"error":"no report"}, status_code=404)

@app.websocket("/ws")
async def ws_endpoint(websocket: WebSocket):
    await websocket.accept()
    ws_clients.append(websocket)
    try:
        while True:
            msg = await websocket.receive_text()
            if msg.startswith("goal:"):
                state["goal"] = msg[5:].strip()
                save_state()
                await websocket.send_text("OK")
            elif msg.startswith("text:"):
                add_input_record("text", msg[5:].strip())
                if state["running"]:
                    if not any(t for t in state["tasks"] if t["title"].startswith("Replan") and t["status"]=="todo"):
                        tid = add_task("Replan a friss input alapján"); set_task_status(tid,"todo")
                save_state()
                await websocket.send_text("OK")
            else:
                await websocket.send_text("OK")
    except WebSocketDisconnect:
        pass
    finally:
        if websocket in ws_clients:
            ws_clients.remove(websocket)

if __name__ == "__main__":
    uvicorn.run("main:app", host="0.0.0.0", port=int(os.getenv("PORT", "8000")), reload=False)


