<style>
body{font-family:system-ui;margin:20px;line-height:1.5}
#log{border:1px solid #ccc;padding:10px;height:240px;overflow:auto;white-space:pre-wrap}
label{display:block;margin-top:10px}
button{margin-top:10px}
#sources, #insights{white-space:pre-wrap}
