<h2>Autonóm Agent</h2>
<div class="container">
<div>
<label>Cél</label>
<input id="goal" style="width:100%" placeholder="Írd ide a célt">
<label>Kezdő szöveg</label>
<textarea id="text" style="width:100%;height:120px" placeholder="Opcionális kezdő anyag"></textarea>
<button id="start">Indítás</button>
<label>Fájlfeltöltés</label>
<input type="file" id="file">
<button id="upload">Feltölt</button>
</div>
<div>
<label>Állapotnapló</label>
<div id="log"></div>
<button id="refresh">Állapot frissítése</button>
<a href="/report" target="_blank">Riport megnyitása</a>
</div>
<div class="full">
<h3>Források</h3>
<pre id="sources"></pre>
<h3>Insightok</h3>
<pre id="insights"></pre>
</div>
</div>
<script>
let ws;
function addLog(t){const el=document.getElementById('log');el.textContent+=t+"\n";el.scrollTop=el.scrollHeight;}
async function startRun(){
  const fd=new FormData();
  fd.append("goal", document.getElementById("goal").value||"");
  fd.append("text", document.getElementById("text").value||"");
  const r=await fetch("/start",{method:"POST",body:fd});
  const j=await r.json();
  addLog("RUN: "+JSON.stringify(j));
  if(!ws||ws.readyState!==1){
    ws=new WebSocket((location.protocol==="https:"?"wss://":"ws://")+location.host+"/ws");
    ws.onmessage=(e)=>addLog(e.data);
  }
}
async function uploadFile(){
  const f=document.getElementById("file").files[0];
  if(!f){return}
  const fd=new FormData(); fd.append("file", f);
  const r=await fetch("/upload",{method:"POST",body:fd});
  const j=await r.json(); addLog("UPLOAD: "+JSON.stringify(j));
}
async function refresh(){
  const r=await fetch("/state"); const j=await r.json();
  document.getElementById("sources").textContent=JSON.stringify(j.sources, null, 2);
  document.getElementById("insights").textContent=JSON.stringify(j.insights, null, 2);
}
document.getElementById("start").onclick=startRun;
document.getElementById("upload").onclick=uploadFile;
document.getElementById("refresh").onclick=refresh;
</script>
</body>
</html>


